{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/lab",
  "data": [
    {
      "name": "state",
      "type": "'unchecked' | 'checked' | 'indeterminate'",
      "description": "Which state to draw. The unchecked circle is an empty ring, not nothing.",
      "required": true
    },
    {
      "name": "size",
      "type": "'sm' | 'md'",
      "description": "Control size. The circle draws at UIKit’s diameters, 18px (sm) or 21.8px (md), centred in the host’s 20px or 24px slot.",
      "default": "'md'"
    },
    {
      "name": "isDisabled",
      "type": "boolean",
      "description": "Draws the disabled look. Purely visual; the owning control keeps the disabled semantics.",
      "default": "false"
    },
    {
      "name": "children",
      "type": "ReactNode",
      "description": "Content drawn inside the circle instead of the mark, e.g. the loading Spinner CheckboxInput passes while a change is pending."
    },
    {
      "name": "xstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for layout customization (margins, positioning, sizing). Must be a stylex.create() value, not an inline style object like style={{}}."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
